type FeeRule = (o: Order) => number;

const rules: Record<string, FeeRule> = {
  blr: () => 30,
  pune: (o) => 20 + 5 * o.km,
};

function deliveryFee(o: Order): number {
  const rule = rules[o.city];
  if (!rule) throw new Error(`no fee rule for ${o.city}`);
  return rule(o);
}

